def clean_url(url:str)->str:
    p = urlsplit(url)
    keep=[]
    for k,v in parse_qsl(p.query, keep_blank_values=True):
        lk = k.lower()
        if lk.startswith('utm_') or lk in {'ref','fbclid','gclid','mc_cid','mc_eid'}:
            continue
        keep.append((k,v))
    return urlunsplit((p.scheme,p.netloc,p.path,urlencode(keep),''))

